python3 - <<'EOF'
import json,collections,re
tr=[json.loads(l) for l in open('benchmark/data/uspto/train.jsonl')]
va=[json.loads(l) for l in open('benchmark/data/uspto/val.jsonl')]
def rt(q):
    m=re.search(r'reaction type is ([^.\n]+)',q); return m.group(1).strip() if m else None
bytype=collections.defaultdict(list)
for r in tr: bytype[rt(r['question'])].append(r['target'])
for t,v in bytype.items():
    print('==',t)
    for x in v: print('   ',x)
print()
# For val: for each gold component, is it present verbatim in a same-type train answer?
tot=hit=0
comps=collections.Counter()
for r in va:
    t=rt(r['question'])
    pool=set()
    for s in bytype[t]:
        for p in s.split('.'): pool.add(p.strip())
    for p in r['target'].split('.'):
        tot+=1
        if p.strip() in pool: hit+=1; comps[p.strip()]+=1
print('val gold components present verbatim in same-type train answers:',hit,'/',tot)
for c,n in comps.most_common(30): print('   ',n,c)
EOF

python3 - <<'EOF'
import json,collections,re
va=[json.loads(l) for l in open('benchmark/data/uspto/val.jsonl')]
rows=[json.loads(l) for l in open('history/results/samples.jsonl')]
def rt(q):
    m=re.search(r'reaction type is ([^.\n]+)',q); return m.group(1).strip() if m else None
idx={}
for i,r in enumerate(va): idx[i]=r
for cand in ['considered_unit_audit','act_ledger_audit','atomic_reference_units']:
    print('=====',cand)
    for i,r in idx.items():
        t=rt(r['question'])
        if 'O=C1CCC(=O)N1Br' in r['target'] or 'CC(C)(C)OC(=O)OC(=O)OC(C)(C)C' in r['target']:
            for s in (0,1):
                m=[x for x in rows if x['candidate']==cand and x['task']=='USPTO' and x['example_index']==i and x['sample_index']==s]
                if m:
                    x=m[0]
                    print(f"  ex{i} s{s} type={t} correct={x.get('was_correct')} jac={x.get('metric')}")
                    print('     pred',repr(x['prediction'])[:150])
                    print('     gold',repr(x['target'])[:150])
EOF

