@staticmethod
def _required_markup(question: str) -> list[str]:
    """Markup the answer has to carry, told apart from markup in the data.

    A bracketed token can be a format requirement or just part of the question's
    content - a chemical formula, a citation, a bracketed atom in a structure. The
    question distinguishes them itself: a requirement is *stated*, so the question
    uses it more than once (in the instruction and again in the format example),
    while a token that occurs once is content. A closing marker of a stated tag is
    required as well.
    """
    if not question:
        return []
    tags = re.findall(r"\[[^\[\]\s]{1,24}\]", question)
    tags += [f"<{name}>" for name in re.findall(r"<([A-Za-z_][A-Za-z0-9_]{0,11})>", question)]
    counts = Counter(tags)
    unique: list[str] = []
    for tag in tags:
        if counts[tag] >= 2 and tag not in unique:
            unique.append(tag)
    for tag in list(unique):
        if tag.startswith("[") and not tag.startswith("[/"):
            closing = "[/" + tag[1:]
            if closing in counts and closing not in unique:
                unique.append(closing)
    return unique[:4]

